--
-- Name: venue_team Owners can view their own team; Type: POLICY; Schema: public; Owner: supabase_admin
--

CREATE POLICY "Owners can view their own team" ON public.venue_team FOR SELECT USING ((EXISTS ( SELECT 1
   FROM public.venues
  WHERE ((venues.id = venue_team.venue_id) AND (venues.owner_id = auth.uid())))));


